  }
  if (Caml_state->requested_major_slice) {
    Caml_state->requested_major_slice = 0;
    Caml_state->young_trigger = Caml_state->young_alloc_start;
    caml_update_young_limit();
    CAML_EV_BEGIN(EV_MAJOR);
    caml_major_collection_slice (-1);
